-- PlantAssure Iteration 3: extra plant data for My Garden (flowering, spread, care, evidence).
-- Source: data/pipeline_i3/output/output_i3.json (Iteration 3 pipeline).
-- Rows are matched to species_data by scientific_name, so they work whatever the species_data ids are.
-- Safe to re-run: the table is recreated.

DROP TABLE IF EXISTS species_passport;
CREATE TABLE species_passport (
  species_id          BIGINT UNSIGNED NOT NULL COMMENT 'species_data.id',
  common_name         VARCHAR(200) NULL COMMENT 'Iteration 3 filled common name (96% coverage)',
  plant_type          VARCHAR(30)  NULL,
  flowers_jan          TINYINT(1)   NULL,
  flowers_feb          TINYINT(1)   NULL,
  flowers_mar          TINYINT(1)   NULL,
  flowers_apr          TINYINT(1)   NULL,
  flowers_may          TINYINT(1)   NULL,
  flowers_jun          TINYINT(1)   NULL,
  flowers_jul          TINYINT(1)   NULL,
  flowers_aug          TINYINT(1)   NULL,
  flowers_sep          TINYINT(1)   NULL,
  flowers_oct          TINYINT(1)   NULL,
  flowers_nov          TINYINT(1)   NULL,
  flowers_dec          TINYINT(1)   NULL,
  flowering_label     VARCHAR(40)  NULL,
  flowering_sources   TINYINT UNSIGNED NOT NULL DEFAULT 0,
  flowering_split     TINYINT(1)   NOT NULL DEFAULT 0,
  resprouting         VARCHAR(60)  NULL,
  vegetative_spread   VARCHAR(60)  NULL,
  dispersal           VARCHAR(100) NULL,
  seedbank_longevity  VARCHAR(60)  NULL,
  wet_soil_tolerance  VARCHAR(60)  NULL,
  evidence_strength   VARCHAR(10)  NOT NULL,
  evidence_available  VARCHAR(120) NOT NULL COMMENT 'comma-separated',
  evidence_missing    VARCHAR(120) NOT NULL COMMENT 'comma-separated',
  vicflora_url        VARCHAR(255) NULL,
  PRIMARY KEY (species_id),
  CONSTRAINT fk_passport_species FOREIGN KEY (species_id) REFERENCES species_data (id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

